const items = $input.all();
const results = [];
for (const item of items) {
  const text = item.json.ParsedResults?.[0]?.ParsedText || '';
  const lines = text.split('\n').filter(l => l.trim());
  const tables = [];
  let currentTable = [];
  let prevWasTabular = false;
  for (const line of lines) {
    const cells = line.split(/\t|\s{2,}|\|/).filter(c => c.trim());
    const isTabular = cells.length >= 2;
    if (isTabular) {
      currentTable.push(cells.map(c => c.trim()));
      prevWasTabular = true;
    } else if (prevWasTabular && currentTable.length > 1) {
      tables.push({
        headers: currentTable[0],
        rows: currentTable.slice(1),
        rowCount: currentTable.length - 1
      });
      currentTable = [];
      prevWasTabular = false;
    } else {
      currentTable = [];
      prevWasTabular = false;
    }
  }
  if (currentTable.length > 1) {
    tables.push({
      headers: currentTable[0],
      rows: currentTable.slice(1),
      rowCount: currentTable.length - 1
    });
  }
  for (let i = 0; i < tables.length; i++) {
    const t = tables[i];
    for (const row of t.rows) {
      const obj = { tableIndex: i + 1 };
      t.headers.forEach((h, idx) => { obj[h] = row[idx] || ''; });
      results.push({ json: obj });
    }
  }
}
if (results.length === 0) {
  results.push({ json: { message: 'No tables detected in PDF' } });
}
return results;

